SELECT 
FROM SYS_NOTIFICATION


        AND NOTIFICATION_TITLE LIKE CONCAT('%', #{queryVO.notificationTitle}, '%')


        AND NOTIFICATION_TYPE = #{queryVO.notificationType}


        AND NOTIFICATION_LEVEL = #{queryVO.notificationLevel}


        AND NOTIFICATION_STATUS = #{queryVO.notificationStatus}


        AND IS_TOP = #{queryVO.isTop}


        AND PUBLISH_SCOPE = #{queryVO.publishScope}


        AND CREATE_BY LIKE CONCAT('%', #{queryVO.createBy}, '%')




                AND DATE(CREATE_TIME) >= #{queryVO.startDate}


                AND TRUNC(CREATE_TIME) >= TO_DATE(#{queryVO.startDate}, 'YYYY-MM-DD')






                AND DATE(CREATE_TIME) <= #{queryVO.endDate}


                AND TRUNC(CREATE_TIME) <= TO_DATE(#{queryVO.endDate}, 'YYYY-MM-DD')




ORDER BY IS_TOP DESC, CREATE_TIME DESC

SELECT 
FROM SYS_NOTIFICATION


        AND NOTIFICATION_TITLE LIKE CONCAT('%', #{notificationTitle}, '%')


        AND NOTIFICATION_TYPE = #{notificationType}


        AND NOTIFICATION_LEVEL = #{notificationLevel}


        AND NOTIFICATION_STATUS = #{notificationStatus}


        AND IS_TOP = #{isTop}


        AND PUBLISH_SCOPE = #{publishScope}


ORDER BY IS_TOP DESC, CREATE_TIME DESC
